window.RUKARTA_EXAMS = {"1":[{"id":"1-001","type":"prefix","stem":"Опытный бухгалтер ни за что не ___ бы такой грубой ошибки в годовом отчёте.","options":["запустил","опустил","пустил","выпустил","отпустил","допустил"],"answer":5,"note":"допустить ошибку; остальные не сочетаются с «ошибки» (род. п. при отрицании)"},{"id":"1-002","type":"prefix","stem":"Сборная, которую считали аутсайдером турнира, ___ убедительную победу над хозяевами и удивила даже самых преданных болельщиков.","options":["одержала","задержала","подержала","сдержала","выдержала","поддержала"],"answer":0,"note":"одержать победу над"},{"id":"1-003","type":"prefix","stem":"Университет ___ всем иностранным студентам бесплатное общежитие на первый год обучения.","options":["оставил","составил","предоставил","поставил","доставил","представил"],"answer":2,"note":"предоставить кому-то что-то"},{"id":"1-004","type":"prefix","stem":"Из-за внезапного ливня организаторам пришлось ___ открытие фестиваля на неделю.","options":["принадлежать","отложить","доложить","предположить","положить","предложить"],"answer":1,"note":"отложить на неделю"},{"id":"1-005","type":"prefix","stem":"Перед выходом мама быстро ___ малышу тёплые варежки и вывела его во двор.","options":["переоделась","дела","одела","надела","надевала","издевалась"],"answer":3,"note":"надеть (вещь) кому-то, а не одеть; быстро + последовательность → совершенный вид"},{"id":"1-006","type":"aspect","stem":"Когда студентка приехала на практику, хозяйка дома сразу ___ её в светлой комнате с видом на реку.","options":["поселяла","положила","поставила","посадила","поселила","селила"],"answer":4,"note":"сразу + разовое действие → совершенный вид; остальные по смыслу не подходят"},{"id":"1-007","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Услышав шаги в коридоре, мальчик спрятал дневник, который до этого лежал на столе»?","options":["Шаги в коридоре послышались уже после того, как мальчик спокойно убрал дневник со стола.","Мальчик нашёл дневник, который кто-то заранее спрятал на столе, и сразу услышал шаги.","Мальчик услышал шаги в коридоре как раз потому, что дневник упал со стола на пол.","Мальчик не успел убрать дневник со стола, потому что в коридоре уже были слышны шаги.","Мальчик достал дневник и положил его на стол, как только услышал шаги в коридоре.","Когда мальчик услышал шаги, он убрал дневник со стола так, чтобы никто его не нашёл."],"answer":5,"note":"A: спрятал = убрал так, чтобы не нашли; остальные меняют порядок, причину или результат"},{"id":"1-008","type":"wrong","stem":"Найдите предложение, в котором глагол употреблён неправильно.","options":["Он засунул записку между страницами и больше никому о ней не рассказывал.","Не засовывай мокрые перчатки в карман: всё намокнет.","Пока мы ждали автобус, он то и дело засунул руки в карманы и вынимал их.","Перед уходом она засунула в сумку зонт на случай дождя.","Каждое утро Игорь засовывал ключи под коврик, а вечером доставал их.","Ребёнок засунул палец в розетку, и мама закричала."],"answer":2,"note":"то и дело → повторяющееся действие → засовывал, а не засунул"},{"id":"1-009","type":"prefix","stem":"Составители правил ___, что в случае отмены рейса пассажирам вернут деньги.","options":["осмотрели","посмотрели","присмотрели","предусмотрели","просмотрели","рассмотрели"],"answer":3,"note":"предусмотреть, что + придаточное"},{"id":"1-010","type":"prefix","stem":"Несмотря на настойчивые просьбы, директор ___ нам в доступе к архиву.","options":["показал","отказал","оказал","заказал","наказал","указал"],"answer":1,"note":"отказать кому-то в чём-то"},{"id":"1-011","type":"prefix","stem":"Друзья решили ___ его день рождения в небольшом ресторане у реки.","options":["отметить","услышать","обнаружить","увидеть","заметить","почувствовать"],"answer":0,"note":"отметить праздник; остальные глаголы восприятия не сочетаются"},{"id":"1-012","type":"prefix","stem":"Если будешь проходить мимо нашего дома, обязательно ___ к нам на чашку чая.","options":["посмотри","взгляни","выгляди","глянь","загляни","присмотри"],"answer":4,"note":"заглянуть к кому-то"},{"id":"1-013","type":"prefix","stem":"Чтобы получить лицензию, фирма обязана полностью ___ все требования противопожарной безопасности.","options":["присмотреть","заметить","соблюсти","осмотреть","понаблюдать","наблюдать"],"answer":2,"note":"соблюсти требования"},{"id":"1-014","type":"aspect","stem":"Не успел он войти в подъезд, как ___ за спиной тяжёлые шаги.","options":["слышал","послушал","осмотрел","слушал","услышал","выслушал"],"answer":4,"note":"не успел … как + совершенный вид"},{"id":"1-015","type":"aspect","stem":"Когда рабочие наконец сняли старые обои, они ___ под ними слой газет времён войны.","options":["осмотрели","обыскивали","обнаруживали","обнаружили","осматривали","обыскали"],"answer":3,"note":"наконец + разовая последовательность → обнаружили"},{"id":"1-016","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Прежде чем звонить в службу поддержки, он поискал решение в интернете, но ничего подходящего не нашёл»?","options":["Он не стал тратить время на интернет и сразу позвонил в службу поддержки.","Служба поддержки сама посоветовала ему поискать решение проблемы в интернете самостоятельно.","Он нашёл решение в интернете и поэтому не стал больше звонить в службу поддержки.","Он сначала позвонил в службу поддержки, а уже потом начал искать ответ в интернете.","Он долго искал в интернете, нашёл подходящий ответ и всё-таки позвонил в службу поддержки.","Сначала он безуспешно поискал ответ в интернете, а потом решил обратиться в службу поддержки."],"answer":5,"note":"порядок: поиск без результата → звонок"},{"id":"1-017","type":"wrong","stem":"Найдите предложение, в котором глагол употреблён неправильно.","options":["Он обыскал по всем карманам, но ключей так и не нашёл.","Дети обыскали весь сад в поисках потерянного мячика.","После долгих поисков он обыскал весь чердак и наконец нашёл билет.","Мальчик отыскал под диваном потерянный носок.","Охранник обыскал каждого, кто входил в здание.","Таможенник попросил пассажира открыть чемодан, чтобы осмотреть его."],"answer":0,"note":"обыскать + прямое дополнение (без «по»)"},{"id":"1-018","type":"prefix","stem":"До дальней деревни мы ___ только к полуночи, потому что мост был закрыт.","options":["разобрались","добрались","забрали","собрали","набрали","убрали"],"answer":1,"note":"добраться до"},{"id":"1-019","type":"prefix","stem":"После лекции студентка осмелилась ___ профессору вопрос, который волновал её весь семестр.","options":["подать","предать","задать","выдать","отдать","сдать"],"answer":2,"note":"задать вопрос"},{"id":"1-020","type":"prefix","stem":"Власти решили ___ дипломата из страны за вмешательство во внутренние дела.","options":["выслать","прислать","дослать","наслать","послать","заслать"],"answer":0,"note":"выслать из страны"},{"id":"1-021","type":"prefix","stem":"Только быстрая реакция диспетчера позволила ___ столкновение двух самолётов.","options":["вернуть","повернуть","предать","превратить","продать","предотвратить"],"answer":5,"note":"предотвратить столкновение"},{"id":"1-022","type":"prefix","stem":"Никто не мог объяснить, как такое вообще могло ___ с таким опытным пилотом.","options":["получить","добраться","удаться","разобраться","случиться","заполучить"],"answer":4,"note":"случиться с кем-то"},{"id":"1-023","type":"aspect","stem":"Он ___ все сбережения за один вечер в казино и остался без гроша.","options":["жертвовал","потратил","подарил","пожертвовал","тратил","дарил"],"answer":1,"note":"за один вечер → совершенный; другие совершенные не подходят по смыслу"},{"id":"1-024","type":"aspect","stem":"Когда охранник отвлёкся на шум, воры успели ___ из витрины три картины.","options":["красть","потерять","купить","украсть","покупать","терять"],"answer":3,"note":"успеть + совершенный вид; витрина: украсть"},{"id":"1-025","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Директор уволил заместителя за то, что тот скрыл от него убытки»?","options":["Директор оставил заместителя на должности, хотя тот скрыл от него информацию об убытках.","Заместитель сам ушёл с работы, потому что директор скрыл от него информацию об убытках.","По решению директора заместитель лишился должности, потому что утаил от него информацию об убытках.","Директор наказал заместителя за потерянные деньги, но всё-таки оставил его на работе.","Директор узнал об убытках только после того, как заместитель потерял работу и ушёл.","Заместитель добился увольнения директора за то, что тот скрыл от всех информацию об убытках."],"answer":2,"note":"увольнение по причине сокрытия убытков"},{"id":"1-026","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Суд лишил водителя, дважды пойманного пьяным, права управлять автомобилем на два года, но оставил ему возможность обжаловать решение»?","options":["Водитель добровольно сдал права на два года, и суд заранее разрешил ему обжаловать любой приговор.","Водитель два года не будет ездить на машине, и решение суда никакому обжалованию не подлежит.","Суд лишил водителя права на обжалование, но разрешил ему продолжать водить машину как раньше.","Водитель, дважды пойманный пьяным, должен заново сдать экзамен и два года ждать решения суда.","Суд на два года запретил водителю обжаловать решение, но разрешил ему по-прежнему ездить на машине.","Водитель, которого дважды задерживали пьяным, два года не сможет водить машину, однако решение суда он вправе оспорить."],"answer":5,"note":"лишить права на срок; обжалование сохраняется"},{"id":"1-027","type":"wrong","stem":"Найдите предложение, в котором глагол употреблён неправильно.","options":["Он поделился мне своим секретом и попросил никому не рассказывать.","Родители пожертвовали значительную сумму детскому приюту.","Бабушка подарила внуку часы, которые носил ещё его дед.","Мы разделили прибыль поровну между всеми участниками проекта.","Она с удовольствием поделилась с подругой рецептом пирога.","Врач определил причину болезни только после повторного анализа."],"answer":0,"note":"поделиться с кем-то, а не поделиться кому-то"},{"id":"1-028","type":"prefix","stem":"Делегация должна ___ в столицу завтра утром скорым поездом.","options":["пережить","прибыть","дождаться","забыть","побыть","выжить"],"answer":1,"note":"прибыть в"},{"id":"1-029","type":"prefix","stem":"Старушка ___ всех своих ровесников и в девяносто лет всё ещё сама ходила за покупками.","options":["дождалась","выжила","пожила","пережила","побыла","прожила"],"answer":3,"note":"пережить кого-то"},{"id":"1-030","type":"prefix","stem":"Президент ___ нового министра финансов указом от первого марта.","options":["завладел","проявил","добавил","означил","назначил","заявил"],"answer":4,"note":"назначить министра"},{"id":"1-031","type":"prefix","stem":"Он едва успел ___ ребёнка за руку, когда тот бросился на проезжую часть.","options":["схватить","собрать","добавить","хватить","добраться","набрать"],"answer":0,"note":"схватить за руку"},{"id":"1-032","type":"prefix","stem":"Новый сотрудник ___ незаурядные организаторские способности уже в первый месяц работы.","options":["начал","появился","объявил","заявил","проявил","стал"],"answer":4,"note":"проявить способности"},{"id":"1-033","type":"prefix","stem":"Лекарство не ___ ему, и врачам пришлось полностью менять схему лечения.","options":["удалось","потребовалось","помогло","повлияло","смогло","понадобилось"],"answer":2,"note":"помочь кому-то"},{"id":"1-034","type":"prefix","stem":"Попробуй ___ в суп немного лимонного сока — вкус станет ярче.","options":["предоставить","добавить","доставить","оставить","выставить","избавиться"],"answer":1,"note":"добавить в суп"},{"id":"1-035","type":"aspect","stem":"Он вдруг ___ и бросил учёбу за месяц до получения диплома.","options":["глупил","жил","хорошел","похорошел","пожил","сглупил"],"answer":5,"note":"вдруг → разовое событие → совершенный вид"},{"id":"1-036","type":"aspect","stem":"Анна и Пётр ___ только через пять лет после знакомства, когда оба закончили учёбу.","options":["жили","прожили","выжили","поженились","пережили","пожили"],"answer":3,"note":"только через пять лет → событие, совершенный вид"},{"id":"1-037","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Узнав о болезни основателя, конкурент постепенно завладел компанией, не потратив на это ни копейки»?","options":["Основатель из-за болезни продал компанию конкуренту и сам отказался брать за неё деньги.","Основатель заболел только после того, как конкурент незаметно получил контроль над его компанией.","Конкурент получил контроль над компанией, но на это ему пришлось потратить очень большие деньги.","Конкурент отказался от покупки компании, когда узнал, что её основатель серьёзно болен.","Узнав о болезни основателя, конкурент мало-помалу взял компанию под свой контроль, ничего за это не заплатив.","Конкурент заплатил основателю полную цену за компанию, как только узнал о его тяжёлой болезни."],"answer":4,"note":"завладеть = взять под контроль"},{"id":"1-038","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Если во время похода вам понадобится помощь, достаточно нажать красную кнопку на браслете — спасатели прибудут в течение часа»?","options":["Спасатели придут на помощь только через час после того, как закончится весь поход.","Вызвать спасателей в походе можно кнопкой на браслете, и они приедут не позже чем через час.","Спасатели приедут быстрее, чем за час, но только если одновременно нажать на две кнопки.","Красную кнопку на браслете нужно нажимать во время любого похода, даже когда помощь не нужна.","Браслет с красной кнопкой следует вернуть спасателям в течение часа после окончания похода.","Красную кнопку на браслете нельзя нажимать, пока с начала похода не пройдёт целый час."],"answer":1,"note":"условие + срок прибытия"},{"id":"1-039","type":"wrong","stem":"Найдите предложение, в котором глагол употреблён неправильно.","options":["Вчера мне удалось дозвониться до него только с третьей попытки.","Она давно умела плавать, хотя всё ещё боялась глубины.","Вчера он наконец сумеет решить эту сложную задачу, над которой бился неделю.","Мальчик не смеет войти в комнату, пока взрослые разговаривают.","Они не смогли бы так быстро закончить работу без вашей помощи.","Я не посмел возразить начальнику при всех."],"answer":2,"note":"вчера + будущее время совершенного вида — ошибка"},{"id":"1-040","type":"prefix","stem":"Сразу после выпускного они решили ___ и больше никогда не встречались.","options":["отстать","устать","настать","расстаться","остаться","встать"],"answer":3,"note":"расстаться; остаться противоречит продолжению"},{"id":"1-041","type":"prefix","stem":"Из-за сильного снегопада авиакомпания была вынуждена ___ все вечерние рейсы и вернуть пассажирам деньги за билеты.","options":["изменить","сменить","перестать","заменить","поменять","отменить"],"answer":5,"note":"отменить + возврат денег"},{"id":"1-042","type":"prefix","stem":"Не могли бы вы ___ мне на пару дней вашу дрель? Я верну её в понедельник.","options":["одолжить","начать","совершить","продолжить","завершить","прекратить"],"answer":0,"note":"одолжить кому-то что-то"},{"id":"1-043","type":"prefix","stem":"Воры сумели ___ в музей через вентиляционную шахту, минуя сигнализацию.","options":["поникнуть","возникнуть","присоединиться","исчезнуть","проникнуть","привыкнуть"],"answer":4,"note":"проникнуть в"},{"id":"1-044","type":"aspect","stem":"Едва мы вышли из леса, туман так же внезапно ___, как и появился.","options":["исчез","исчезал","проникал","возник","возникал","проник"],"answer":0,"note":"внезапно → совершенный вид; возник противоречит «как и появился»"},{"id":"1-045","type":"aspect","stem":"Уже через неделю я ___ к новому графику и стал просыпаться без будильника.","options":["присоединялся","начинал","присоединился","привыкал","начал","привык"],"answer":5,"note":"уже через неделю + результат → совершенный вид"},{"id":"1-046","type":"aspect","stem":"Спортсмену удалось ___ последствия тяжёлой травмы и вернуться на пьедестал.","options":["улучшить","ухудшать","преодолевать","преодолеть","ухудшить","улучшать"],"answer":3,"note":"удалось + совершенный вид"},{"id":"1-047","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Не желая, чтобы отец повлиял на его выбор профессии, Антон скрыл от него результаты экзаменов»?","options":["Антон выбрал профессию, которую посоветовал отец, и поэтому скрыл от него результаты экзаменов.","Антон не рассказал отцу о результатах экзаменов, потому что хотел сам решить, кем ему стать.","Отец скрыл от Антона результаты экзаменов, потому что хотел повлиять на его выбор профессии.","Антон не сдавал экзамены, чтобы отец не мог повлиять на выбор его будущей профессии.","Антон показал отцу результаты экзаменов, чтобы тот помог ему выбрать будущую профессию.","Отец повлиял на выбор профессии, хотя Антон старательно скрывал от него результаты экзаменов."],"answer":1,"note":"скрыл, чтобы отец не повлиял на выбор"},{"id":"1-048","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Общая беда так породнила соседей, что они стали встречать праздники вместе»?","options":["Общая беда заставила соседей разъехаться и отмечать праздники теперь по отдельности.","Соседи пережили общую беду, а после неё перестали встречать праздники вместе.","Из-за общего несчастья соседи сблизились, как родные, и теперь вместе встречают праздники.","Совместные праздники так сблизили соседей, что вместе они смогли справиться с бедой.","Соседи стали родственниками друг другу и поэтому сильно поссорились из-за праздников.","Соседи отмечали праздники вместе ещё до того, как общая беда их внезапно разделила."],"answer":2,"note":"беда → сближение → совместные праздники"},{"id":"1-049","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Правительство увеличило пособия многодетным семьям, однако из-за роста цен покупательная способность семей практически не изменилась»?","options":["Пособия многодетным семьям остались прежними, и именно поэтому цены в магазинах заметно выросли.","Благодаря росту пособий многодетные семьи стали покупать намного больше, чем они покупали раньше.","Правительство уменьшило выплаты, зато цены упали, и семьи смогли покупать столько же, сколько раньше.","Из-за стремительного роста цен правительство отменило все пособия многодетным семьям.","Цены в магазинах выросли только потому, что правительство увеличило пособия многодетным семьям.","Выплаты многодетным семьям стали больше, но, поскольку всё подорожало, купить на них можно примерно столько же."],"answer":5,"note":"пособия выросли, цены выросли, эффект нулевой"},{"id":"1-050","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Склад сгорел дотла ещё до приезда пожарных, хотя их вызвали сразу, как только заметили дым»?","options":["Пожарных вызвали без промедления, но огонь успел полностью уничтожить склад раньше, чем они приехали.","Дым заметили уже после того, как склад давно сгорел дотла, поэтому пожарных не вызывали.","Пожарных не вызывали, потому что склад ещё не горел, когда они уже подъехали к нему.","Склад сгорел только потому, что пожарных вызвали слишком поздно, когда огонь уже был сильным.","Склад загорелся из-за того, что пожарные очень долго не приезжали по вызову.","Пожарные приехали вовремя, быстро потушили огонь и сумели спасти склад от полного уничтожения."],"answer":0,"note":"вызвали сразу, но не успели"},{"id":"1-051","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Врач посоветовал пациенту прекратить курить, но тот пообещал бросить только после отпуска»?","options":["Пациент отказался слушать врача и заявил, что вообще никогда не бросит курить.","Врач советовал бросить курить немедленно, а пациент согласился сделать это лишь после отпуска.","Врач запретил пациенту ехать в отпуск, пока тот окончательно не бросит курить.","Врач разрешил пациенту курить до самого отпуска, а бросить велел только после него.","Пациент бросил курить сразу после совета врача, а свой отпуск решил перенести.","Пациент посоветовал врачу бросить курить после отпуска, и врач с этим согласился."],"answer":1,"note":"совет: сейчас; ответ пациента: после отпуска"},{"id":"1-052","type":"wrong","stem":"Найдите предложение, в котором глагол употреблён неправильно.","options":["Альпинисты достигли вершины на рассвете.","Он давно привык вставать в шесть утра.","Мы достигли до вершины только к вечеру.","Цены на топливо выросли почти вдвое по сравнению с прошлым годом.","Фирма внедрила новую систему учёта ещё в прошлом году.","Температура воздуха начала быстро падать после захода солнца."],"answer":2,"note":"достичь чего-то, без «до»"},{"id":"1-053","type":"prefix","stem":"Ему так ___ однообразная работа, что он решил подать заявление об уходе.","options":["поела","съела","пообедала","обедала","надоела","поедала"],"answer":4,"note":"надоесть (кому-то что-то)"},{"id":"1-054","type":"prefix","stem":"После собрания он пошёл в бар и там ___ в стельку, так что утром ничего не помнил.","options":["покурил","попил","выпил","напился","поспал","поужинал"],"answer":3,"note":"напиться в стельку — устойчивое выражение"},{"id":"1-055","type":"prefix","stem":"Чтобы не опоздать на поезд, нам придётся ___ в четыре утра.","options":["уснуть","заснуть","проснуться","выспаться","переспать","поспать"],"answer":2,"note":"проснуться; остальные абсурдны"},{"id":"1-056","type":"aspect","stem":"Малыш сидел тихо, но, как только мама вышла из комнаты, вдруг ___.","options":["курил","заплакал","дышал","подышал","плакал","покурил"],"answer":1,"note":"вдруг → совершенный вид"},{"id":"1-057","type":"aspect","stem":"Только на вокзале, когда поезд уже тронулся, он наконец решился и ___ её на прощание.","options":["будил","накормил","разбудил","кормил","целовал","поцеловал"],"answer":5,"note":"наконец решился → разовое действие"},{"id":"1-058","type":"aspect","stem":"В той катастрофе ___ шестеро пассажиров, остальных удалось спасти.","options":["погибли","подышали","улыбнулись","улыбались","дышали","гибли"],"answer":0,"note":"итог события → совершенный вид"},{"id":"1-059","type":"aspect","stem":"Мы так проголодались, что хозяйка дома тут же ___ нас горячим борщом.","options":["улыбнулась","улыбалась","кормила","накормила","мёрзла","замёрзла"],"answer":3,"note":"тут же → совершенный вид"},{"id":"1-060","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Если студент заболеет накануне экзамена, ему разрешат сдавать позже, при условии что он принесёт справку»?","options":["Студенту разрешат сдавать экзамен позже, даже если он не принесёт никакой медицинской справки.","Студент сдаст экзамен позже, потому что он уже заболел и заранее принёс врачебную справку.","Если студент принесёт справку о болезни, то сдавать экзамен ему вообще не придётся.","Справка нужна для того, чтобы допустить студента к экзамену именно в назначенный день.","В случае болезни перед экзаменом студент сможет сдать его позднее, но только с медицинской справкой.","Экзамен перенесут для всех студентов группы сразу, если хоть один из них заболеет."],"answer":4,"note":"условие + требование справки"},{"id":"1-061","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Я просил её разбудить меня в шесть, но она забыла, и я проспал важную встречу»?","options":["Я просил её не будить меня в шесть, поэтому и проспал эту важную встречу.","Я просил её поднять меня в шесть, но она не сделала этого, и я не проснулся вовремя.","Я забыл попросить её о побудке, поэтому важная встреча так и не состоялась.","Она разбудила меня ровно в шесть, но я всё равно сильно опоздал на встречу.","Она напомнила мне о встрече, но к этому времени я уже успел уйти из дома.","Я сам разбудил её в шесть утра, и потом мы вместе проспали эту встречу."],"answer":1,"note":"просил, она забыла, я проспал"},{"id":"1-062","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Прежде чем участвовать в соревнованиях, спортсменка решила потренироваться ещё неделю и только потом подать заявку»?","options":["Спортсменка решила провести ещё неделю в тренировках, а заявку подать уже после этого.","Спортсменка отказалась от соревнований, потому что ей не хватило недели на подготовку.","Заявку на соревнования подали за неделю до того, как начались тренировки.","Спортсменка сначала подала заявку на соревнования, а после этого тренировалась ещё целую неделю.","Спортсменка уже неделю тренировалась, поэтому сразу после этого подала заявку на участие.","Спортсменка не хотела готовиться к соревнованиям и поэтому сразу подала заявку."],"answer":0,"note":"сначала неделя тренировок, потом заявка"},{"id":"1-063","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Раненый лежал так тихо, что никто не заметил, как он пошевелился и открыл глаза»?","options":["Раненый так сильно двигался, что все увидели, как он открыл глаза.","Раненый закрыл глаза и замер, чтобы никто не заметил, что он двигался.","Никто не заметил раненого, потому что он лежал тихо и ни разу не открыл глаз.","Раненый лежал совершенно неподвижно, и все сразу заметили, что он открыл глаза.","Все заметили, что раненый двинулся, но не увидели, как он открыл глаза.","Раненый чуть заметно шелохнулся и открыл глаза, но никто этого не увидел."],"answer":5,"note":"движение и открытые глаза остались незамеченными"},{"id":"1-064","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Врачи вылечили его от редкой болезни, но предупредили, что полностью исключить рецидив нельзя»?","options":["Врачи предупредили его о рецидиве, потому что так и не смогли вылечить болезнь.","Рецидив уже начался, и теперь врачи пытаются снова вылечить его от болезни.","Врачам не удалось справиться с болезнью, зато они твёрдо пообещали, что рецидива не будет.","Он выздоровел, и врачи гарантировали ему, что болезнь никогда больше не вернётся.","Болезнь удалось победить, однако врачи не могут обещать, что она никогда не вернётся.","Врачи вылечили его от обычной болезни, а редкая болезнь у него так и осталась."],"answer":4,"note":"вылечили, но рецидив возможен"},{"id":"1-065","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Бабушка умерла ещё до того, как внук родился, но он хорошо знал её по рассказам родителей»?","options":["Бабушка умерла уже после рождения внука, поэтому он хорошо знал её лично.","Родители внука умерли до его рождения, и о бабушке он знает только по рассказам.","Внук не застал бабушку живой, потому что она ушла из жизни до его рождения, но много слышал о ней.","Внук родился, когда бабушка ещё была жива, но почему-то совсем не знал её.","Внук знал бабушку лишь по рассказам родителей, потому что она жила очень далеко.","Бабушка умерла, когда внук уже был взрослым человеком, и знал её по рассказам родителей."],"answer":2,"note":"умерла до рождения внука"},{"id":"1-066","type":"wrong","stem":"Найдите предложение, в котором глагол употреблён неправильно.","options":["Малыш проснулся посреди ночи и громко заплакал.","Девочка улыбнулась маме и побежала в школу.","Пациента положили в больницу, чтобы вылечить от тяжёлой болезни.","Он улыбнулся на меня и пошёл дальше.","Он выпил стакан воды и снова лёг спать.","Учитель строго посмотрел на него, и тот сразу замолчал."],"answer":3,"note":"улыбнуться кому-то, а не на кого-то"},{"id":"1-067","type":"prefix","stem":"Прежде чем нажать «отправить», я хочу успеть ___, все ли приложения на месте.","options":["проверять","довериться","поверить","проверить","верить","поверять"],"answer":3,"note":"успеть + совершенный вид; проверить, все ли"},{"id":"1-068","type":"prefix","stem":"Он собирался уехать в понедельник, но в последний момент ___ уезжать и остался дома.","options":["подумал","придумал","думал","задумал","обдумал","передумал"],"answer":5,"note":"передумать + инфинитив"},{"id":"1-069","type":"prefix","stem":"Суд ___ подсудимого виновным в мошенничестве в особо крупном размере.","options":["признал","знал","опознал","назначил","узнал","осознал"],"answer":0,"note":"признать кого-то виновным"},{"id":"1-070","type":"prefix","stem":"Позвони мне завтра утром и ___ о встрече, а то я точно забуду.","options":["помни","напомни","запомни","вспомни","поверь","упомяни"],"answer":1,"note":"напомнить кому-то о чём-то"},{"id":"1-071","type":"prefix","stem":"Болезнь ___ у него последние силы, и он почти не вставал с постели.","options":["поняла","сняла","наняла","заняла","отняла","обняла"],"answer":4,"note":"отнять силы у кого-то"},{"id":"1-072","type":"prefix","stem":"Преподавателю так и не удалось ___ студентам, почему эта задача имеет два решения.","options":["выяснить","признать","объяснить","опознать","узнать","осознать"],"answer":2,"note":"объяснить кому-то"},{"id":"1-073","type":"prefix","stem":"Он был уверен в успехе, но в последний момент вдруг ___, правильно ли поступил.","options":["сомневался","ошибся","помечтал","засомневался","мечтал","запутался"],"answer":3,"note":"вдруг → начало действия, за-"},{"id":"1-074","type":"aspect","stem":"За пять минут мы ___ обе версии отчёта и нашли три расхождения.","options":["ошибались","сравнили","мечтали","ошиблись","сравнивали","помечтали"],"answer":1,"note":"за + срок → совершенный вид"},{"id":"1-075","type":"aspect","stem":"Как только в комнате стало тихо, я смог ___ и дописать главу.","options":["ошибаться","запутываться","запутаться","сосредоточиваться","сосредоточиться","ошибиться"],"answer":4,"note":"как только + разовое событие → совершенный вид"},{"id":"1-076","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Эксперты опровергли слухи о закрытии завода, предъявив журналистам договоры, подписанные на следующий год»?","options":["Завод закрыли после того, как эксперты показали журналистам подписанные договоры.","Журналисты опровергли слова экспертов, получив договоры о закрытии завода на следующий год.","Специалисты доказали, что завод закрываться не собирается, показав журналистам договоры на следующий год.","Эксперты не смогли доказать, что завод закроется, потому что у них не было никаких договоров.","Эксперты подтвердили слухи о закрытии завода, показав журналистам договоры на следующий год.","Журналисты показали экспертам договоры, из которых следовало, что завод скоро закроется."],"answer":2,"note":"опровергли слухи документами"},{"id":"1-077","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Чтобы получить грант, учёному пришлось письменно обосновать, зачем ему нужно дорогое оборудование, и собрать три рекомендации»?","options":["Чтобы купить оборудование, учёный написал рекомендательные письма для трёх своих коллег.","Учёному отказали в гранте, потому что он не объяснил, зачем ему нужно такое оборудование.","Учёному выдали дорогое оборудование только потому, что он заранее собрал три рекомендации.","Рекомендации потребовались только после того, как грант уже был получен и оборудование куплено.","Учёный получил грант без каких-либо объяснений, потому что у него уже было три рекомендации.","Для получения гранта учёный должен был письменно объяснить, зачем ему оборудование, и собрать три рекомендательных письма."],"answer":5,"note":"условия получения гранта"},{"id":"1-078","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Директор поручил заместителю проконтролировать, чтобы заказ отправили вовремя»?","options":["Директор дал заместителю задание убедиться, что заказ уйдёт к клиенту в срок.","Директор сам отправил заказ вовремя, потому что заместитель его не проверил.","Заместитель поручил директору следить за тем, как отправляют заказ клиенту.","Заместитель попросил директора поручить ему отправку заказа в срок.","Заказ отправили вовремя только благодаря директору, а не его заместителю.","Директор запретил заместителю вмешиваться в отправку заказа клиентам."],"answer":0,"note":"поручение проследить за сроком"},{"id":"1-079","type":"wrong","stem":"Найдите предложение, в котором глагол употреблён неправильно.","options":["Мы ошиблись адресом и час ждали не там.","Учитель ошибся на её оценку, и пришлось пересдавать.","Я ошибся дверью и попал в чужую квартиру.","Он ошибся в расчётах, поэтому смета оказалась неверной.","Следователь ошибался насчёт мотивов преступника.","Не ошибись в выборе профессии — от этого зависит многое."],"answer":1,"note":"ошибиться в чём-то/чем-то, не «на»"},{"id":"1-080","type":"wrong","stem":"Найдите предложение, в котором глагол употреблён неправильно.","options":["Он давно мечтал о поездке в Японию.","Мальчик мечтает стать лётчиком.","Мы мечтаем отдыхом у моря всё лето.","Девочка мечтала, глядя в окно на падающий снег.","Дядя мечтал увидеть родные края перед смертью.","Она мечтала, что когда-нибудь выйдет на сцену Большого театра."],"answer":2,"note":"мечтать о чём-то"}],"2":[{"id":"2-001","type":"motion","stem":"Никто не мог понять, что именно ___ в ту ночь в старом доме.","options":["сошло","отошло","дошло","произошло","нашло","вошло"],"answer":3,"note":"произойти = случиться"},{"id":"2-002","type":"motion","stem":"Чтобы не застрять в пробке, водитель решил ___ перекрытый участок по соседним дворам.","options":["объехать","переехать","въехать","отъехать","выехать","доехать"],"answer":0,"note":"объехать по дворам"},{"id":"2-003","type":"motion","stem":"Только быстрая реакция помогла водителю ___ столкновения со встречной машиной.","options":["сбежать","добежать","избежать","забежать","пробежать","убежать"],"answer":2,"note":"избежать + род. п."},{"id":"2-004","type":"motion","stem":"Из-за сильного шума нужное слово совсем ___ у меня из головы.","options":["отлетело","вылетело","влетело","облетело","долетело","залетело"],"answer":1,"note":"вылететь из головы"},{"id":"2-005","type":"motion","stem":"Он мечтал ___ Ла-Манш без остановок и без сопровождающей лодки.","options":["доплыть","вплыть","заплыть","отплыть","переплыть","выплыть"],"answer":4,"note":"переплыть + вин. п."},{"id":"2-006","type":"motion","stem":"Организм ребёнка с трудом ___ такую высокую температуру.","options":["занёс","принёс","внёс","унёс","донёс","перенёс"],"answer":5,"note":"перенести = выдержать"},{"id":"2-007","type":"motion","stem":"Постоянные упрёки в конце концов ___ её до слёз.","options":["подвели","вывели","завели","довели","ввели","свели"],"answer":3,"note":"довести до слёз"},{"id":"2-008","type":"motion","stem":"Нам просто ___: мы успели на последний поезд за минуту до отправления.","options":["отвезло","перевезло","повезло","довезло","завезло","привезло"],"answer":2,"note":"повезти (безл.) = посчастливиться"},{"id":"2-009","type":"motion","stem":"Мы еле ___ тяжёлый чемодан до третьего этажа.","options":["оттащили","втащили","вытащили","перетащили","дотащили","протащили"],"answer":4,"note":"дотащить до"},{"id":"2-010","type":"motion","stem":"Кошка забралась на самую верхушку дерева и никак не могла ___ оттуда.","options":["перелезть","долезть","пролезть","залезть","влезть","слезть"],"answer":5,"note":"слезть оттуда (вниз)"},{"id":"2-011","type":"motion","stem":"Раненый из последних сил пытался ___ до ближайшей палатки.","options":["отползти","доползти","выползти","заползти","подползти","вползти"],"answer":1,"note":"доползти до"},{"id":"2-012","type":"motion","stem":"К вечеру измученные путники наконец ___ до ближайшей деревни.","options":["добрели","забрели","подошли","побрели","отошли","набрели"],"answer":0,"note":"добрести до (подошли до — неверное управление)"},{"id":"2-013","type":"motion","stem":"Стая волков неожиданно ___ на отставшего от обоза путника.","options":["попала","пропала","упала","спала","напала","сошла"],"answer":4,"note":"напасть на"},{"id":"2-014","type":"motion","stem":"Двое подростков решили ___ чужой автомобиль и покататься по ночному городу.","options":["прогнать","догнать","загнать","отогнать","пригнать","угнать"],"answer":5,"note":"угнать автомобиль"},{"id":"2-015","type":"motion","stem":"Увидев счёт, он вдруг ___ в ресторане настоящий скандал.","options":["закатил","укатил","выкатил","подкатил","докатил","вкатил"],"answer":0,"note":"закатить скандал"},{"id":"2-016","type":"motion","stem":"Светофор переключился на зелёный, и колонна резко ___ с места.","options":["поторопилась","упала","двигалась","двинулась","торопилась","падала"],"answer":3,"note":"двинуться с места"},{"id":"2-017","type":"prefix","stem":"Закончив подготовку площадки, строители смогли ___ к заливке фундамента.","options":["вступить","приступить","отступить","наступить","поступить","выступить"],"answer":1,"note":"приступить к"},{"id":"2-018","type":"prefix","stem":"Новичок неожиданно легко ___ с заданием, которое не давалось даже опытным коллегам.","options":["поправился","направил","справился","управлял","исправил","отправил"],"answer":2,"note":"справиться с"},{"id":"2-019","type":"prefix","stem":"Свидетель подробно ___ внешность грабителя, и по его рассказу составили фоторобот.","options":["обыскал","подписал","осмотрел","записал","написал","описал"],"answer":5,"note":"описать внешность"},{"id":"2-020","type":"prefix","stem":"Команда почти весь матч вела в счёте, но в последние минуты неожиданно ___ и вылетела из турнира.","options":["проиграла","поиграла","выиграла","сыграла","играла","победила"],"answer":0,"note":"проиграть; вылетела"},{"id":"2-021","type":"prefix","stem":"Группа инженеров ___ новую модель двигателя, которая расходует вдвое меньше топлива.","options":["работала","написала","поработала","сработала","разработала","заработала"],"answer":4,"note":"разработать модель"},{"id":"2-022","type":"aspect","stem":"За один вечер художник ___ портрет, на который у других ушли бы недели.","options":["потанцевал","нарисовал","строил","танцевал","построил","рисовал"],"answer":1,"note":"за + срок → совершенный вид"},{"id":"2-023","type":"aspect","stem":"Спустя двадцать лет она наконец ___ свою детскую мечту и открыла собственный театр.","options":["отрегулировала","создала","создавала","осуществила","осуществляла","регулировала"],"answer":3,"note":"наконец → результат"},{"id":"2-024","type":"aspect","stem":"За пять минут мастер ___ тормоза, и машина перестала скрипеть.","options":["регулировал","пробовал","отрегулировал","попробовал","планировал","спланировал"],"answer":2,"note":"за + срок → совершенный вид"},{"id":"2-025","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Руководитель спланировал отпуска сотрудников так, чтобы в офисе всегда оставалось не меньше трёх человек»?","options":["Отпуска были распределены по графику таким образом, чтобы на рабочем месте постоянно находились минимум трое.","Отпуска сотрудников назначили на разные месяцы, из-за чего иногда в офисе никого не оставалось.","Все сотрудники ушли в отпуск одновременно, но в офисе всё равно остались работать три человека.","Руководитель запретил брать отпуск тем, кто проработал в этом офисе меньше трёх лет.","В офисе всегда работало не меньше трёх человек, и поэтому отпуска пришлось полностью отменить.","Руководитель разрешил уходить в отпуск когда угодно и оставил в офисе только троих сотрудников."],"answer":0,"note":"график отпусков с минимумом сотрудников"},{"id":"2-026","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Благодаря этому проекту удалось создать сотни рабочих мест в городе, где раньше почти не было промышленности»?","options":["Проект предназначен для города с развитой промышленностью, где давно не хватает рабочих рук.","В городе, где было много заводов, проект сохранил рабочие места и не добавил ни одного нового.","Сотни рабочих мест в городе появились ещё до проекта, который лишь немного изменил положение.","Проект принёс городу сотни новых рабочих мест, хотя прежде заводов и фабрик там почти не существовало.","Проект закрыл сотни рабочих мест в городе, где прежде промышленность была очень развита.","Благодаря проекту жители уехали из города, потому что промышленности там совсем не осталось."],"answer":3,"note":"создали рабочие места там, где промышленности не было"},{"id":"2-027","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Школьники самостоятельно организовали благотворительный концерт, а вырученные деньги передали приюту для животных»?","options":["Школьники пришли на концерт, который устроили взрослые, и отдали свои деньги приюту для животных.","Концерт провели в самом приюте для животных, а деньги за него получили сами школьники.","Ребята сами подготовили и провели концерт ради помощи, а собранные средства отдали приюту для животных.","Школьники отказались участвовать в концерте, потому что деньги нужно было передать приюту для животных.","Школьники собрали деньги для приюта, но концерт так и не смогли провести без помощи взрослых.","Учителя подготовили концерт, а школьники только продавали билеты, и деньги достались самой школе."],"answer":2,"note":"самостоятельно подготовили концерт; деньги — приюту"},{"id":"2-028","type":"wrong","stem":"Найдите предложение, в котором глагол употреблён неправильно.","options":["Для этого эксперимента мы использовали новейшее оборудование.","Позвольте мне воспользоваться вашим телефоном, мой разрядился.","Он воспользовался случаем и предложил ей руку и сердце.","Нельзя пользоваться лифтом во время пожара.","Она воспользовалась мою помощь и успешно сдала экзамен.","Лодкой можно пользоваться только в хорошую погоду."],"answer":4,"note":"воспользоваться чем-то (твор. п.)"},{"id":"2-029","type":"prefix","stem":"Он так ___ историей, что стал проводить в библиотеке все выходные.","options":["влёк","отвлёк","привлёк","извлёк","развлёкся","увлёкся"],"answer":5,"note":"увлечься чем-то"},{"id":"2-030","type":"prefix","stem":"Он так легко ___ в каждую новую знакомую, что друзья давно перестали принимать его чувства всерьёз.","options":["полюбил","влюблялся","любил","возненавидел","понравился","обожал"],"answer":1,"note":"влюбляться в + вин. п., повторяющееся действие"},{"id":"2-031","type":"prefix","stem":"Извините, что я ___ вас так поздно, но у меня срочный вопрос.","options":["заботился","скучал","соскучился","побеспокоил","успокоил","позаботился"],"answer":3,"note":"формула извинения: побеспокоить"},{"id":"2-032","type":"prefix","stem":"Я не хотел ___ вас, просто хотел пошутить.","options":["скучать","понадеяться","успокоить","пугаться","испугаться","напугать"],"answer":5,"note":"напугать кого-то"},{"id":"2-033","type":"prefix","stem":"Не волнуйся, о билетах я ___ заранее.","options":["постараюсь","понадеюсь","позабочусь","поволнуюсь","пожалею","потерплю"],"answer":2,"note":"позаботиться о билетах"},{"id":"2-034","type":"aspect","stem":"Увидев подарок, девочка мгновенно ___ и запрыгала по комнате.","options":["понервничала","обрадовалась","нервничала","повеселилась","веселилась","радовалась"],"answer":1,"note":"едва … → мгновенная реакция, совершенный вид"},{"id":"2-035","type":"aspect","stem":"Ему наконец удалось ___ обидчику, который двадцать лет унижал его семью.","options":["отомстить","страдать","потерпеть","пострадать","мстить","терпеть"],"answer":0,"note":"успеть + совершенный вид; мстить кому"},{"id":"2-036","type":"aspect","stem":"Он долго не мог принять случившееся, но в конце концов ___ с потерей.","options":["гордился","смирялся","пострадал","возгордился","смирился","страдал"],"answer":4,"note":"в конце концов → результат; смириться с"},{"id":"2-037","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Она так и не простила бы его, если бы не увидела, как искренне он раскаивается»?","options":["Она увидела его раскаяние, но всё равно решила никогда не прощать его.","Она простила его сразу, ещё до того, как он успел признать свою вину.","Она хотела его простить, но не поверила в искренность его слов.","Он раскаивается, потому что она так и не простила его до сих пор.","Он перестал раскаиваться, когда она наконец простила его за всё случившееся.","Только искреннее раскаяние заставило её отказаться от обиды и в конце концов простить его."],"answer":5,"note":"простила благодаря раскаянию"},{"id":"2-038","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Новый сотрудник удивил всех тем, что выучил за месяц язык, который остальные не могли освоить годами»?","options":["Язык, который новичок учил годами, коллеги освоили всего за один месяц.","Все были поражены тем, что новичок за месяц освоил язык, на который у коллег уходили годы.","Новичок удивил коллег тем, что отказался учить язык, на изучение которого нужны годы.","Новый сотрудник не смог освоить язык за месяц, поэтому коллеги были удивлены.","Коллеги выучили язык быстрее, чем новичок, которому на это потребовались годы.","Новичок удивился, что коллеги выучили язык за месяц, хотя им понадобились годы."],"answer":1,"note":"новичок быстрее всех"},{"id":"2-039","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Она боялась обидеть его отказом, поэтому долго не решалась сказать, что не придёт на свадьбу»?","options":["Он долго не решался сказать ей, что свадьбу придётся отменить из-за её отказа.","Он обиделся на неё за отказ и поэтому не позвал её на свадьбу вовсе.","Она отказала ему резко, потому что хотела, чтобы он обиделся и не приглашал её больше.","Она сразу сказала ему, что придёт на свадьбу, и совсем не побоялась его обидеть.","Ей не хотелось огорчать его, и потому она тянула с признанием, что на свадьбе её не будет.","Она долго колебалась, идти ли на свадьбу, и наконец решила сделать ему приятное."],"answer":4,"note":"из деликатности откладывала отказ"},{"id":"2-040","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Лектору удалось заинтересовать даже тех студентов, которые обычно спали на его парах»?","options":["Преподаватель сумел пробудить интерес и у тех слушателей, кто раньше дремал на занятиях.","Лектор не смог привлечь внимание тех студентов, которые обычно спали на его занятиях.","Лектор заставил заснуть даже тех, кто обычно внимательно слушал его на занятиях.","Студенты, которые обычно спали, заинтересовали лектора своей необычной манерой отдыхать.","Только самые заинтересованные студенты не спали на лекции, поэтому остальных лектор не будил.","Студенты уснули на лекции, потому что лектор слишком увлёкся собственной темой."],"answer":0,"note":"интерес у тех, кто раньше спал"},{"id":"2-041","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Перед экзаменом профессор пожелал студентам не терять голову и вспомнить всё, чему их учили»?","options":["Профессор пообещал, что экзамен отменят, если студенты вспомнят всё пройденное.","Студенты пожелали профессору удачи, потому что он забыл всё, чему их учили.","Накануне экзамена преподаватель выразил надежду, что студенты не растеряются и вспомнят пройденное.","Профессор напомнил, что после экзамена все быстро забудут то, чему их учили.","Профессор потребовал, чтобы студенты потеряли голову и забыли всё, чему их учили.","Студенты пожелали, чтобы профессор не терял голову перед самым экзаменом."],"answer":2,"note":"пожелание перед экзаменом"},{"id":"2-042","type":"wrong","stem":"Найдите предложение, в котором глагол употреблён неправильно.","options":["Он давно интересуется историей искусства.","Мы надеялись на хорошую погоду, но весь день шёл дождь.","Меня очень заинтересовала эта книга.","Она всегда гордилась на свою младшую сестру.","Мальчик боится собак и поэтому обходит их стороной.","Родители гордятся успехами сына."],"answer":3,"note":"гордиться кем-то (твор. п.)"},{"id":"2-043","type":"prefix","stem":"Мне с трудом удалось ___ брата поехать со мной, потому что он не хотел покидать дом.","options":["поговорить","договорить","уговорить","сказать","заговорить","разговорить"],"answer":2,"note":"уговорить кого-то + инфинитив"},{"id":"2-044","type":"prefix","stem":"Я весь день пытался ___ до врача, но телефон был постоянно занят.","options":["позвонить","позвать","перезвонить","звать","звонить","дозвониться"],"answer":5,"note":"дозвониться до"},{"id":"2-045","type":"prefix","stem":"Родители долго спорили, как ___ новорождённую дочь, и в итоге выбрали старинное имя.","options":["сказать","спросить","попросить","вызвать","назвать","позвать"],"answer":4,"note":"назвать ребёнка (именем)"},{"id":"2-046","type":"prefix","stem":"Совет директоров ___ его в должности генерального директора на очередной срок.","options":["поздравил","посоветовал","предупредил","утвердил","пригласил","подтвердил"],"answer":3,"note":"утвердить в должности"},{"id":"2-047","type":"prefix","stem":"Администрация отеля обязана заранее ___ гостям о любых изменениях в расписании завтрака.","options":["сообщить","общаться","возразить","повторить","поздравить","пообщаться"],"answer":0,"note":"сообщить кому о чём"},{"id":"2-048","type":"prefix","stem":"Мать на коленях ___ судью пощадить её сына, но тот остался непреклонен.","options":["умолила","умоляла","молилась","спросила","помолилась","допросила"],"answer":1,"note":"попытка без результата → несовершенный вид умоляла (умолила = добилась)"},{"id":"2-049","type":"prefix","stem":"Заблудившись, она подошла к прохожему и ___, как пройти к вокзалу.","options":["просила","позвонила","спросила","попросила","допросила","позвала"],"answer":2,"note":"спросить, как + вопрос"},{"id":"2-050","type":"prefix","stem":"Услышав приближающиеся шаги, мужчины вдруг ___ и спрятали карты.","options":["замолчали","замалчивали","общались","молчали","помолчали","сообщали"],"answer":0,"note":"вдруг → замолчать"},{"id":"2-051","type":"prefix","stem":"Когда ему предложили поменяться местами, пассажир вдруг громко ___.","options":["помолчал","запротестовал","поговорил","протестовал","молчал","замолчал"],"answer":1,"note":"вдруг громко → начало действия, запротестовал"},{"id":"2-052","type":"aspect","stem":"Он вдруг так громко ___, что с дерева слетели все птицы.","options":["молчал","подумал","думал","помолчал","крикнул","кричал"],"answer":4,"note":"вдруг → разовое действие"},{"id":"2-053","type":"aspect","stem":"Он уже собирался уходить, когда вспомнил, что забыл ___ хозяев за ужин.","options":["благодарить","поздравлять","поздравить","навещать","навестить","поблагодарить"],"answer":5,"note":"забыл + совершенный вид для разового действия"},{"id":"2-054","type":"aspect","stem":"Он попросил меня ___ последнюю фразу ещё один раз, потому что не расслышал.","options":["голосовать","болтать","повторять","повторить","проголосовать","поболтать"],"answer":3,"note":"один раз → совершенный вид"},{"id":"2-055","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Врач запретил ему подниматься по лестнице без посторонней помощи, пока не заживёт нога»?","options":["Ему нельзя подниматься по лестнице даже с чужой помощью, хотя нога у него уже зажила.","Нога заживёт только в том случае, если он будет часто подниматься по лестнице один.","Ему запрещено вызывать врача, пока он не поднимется по лестнице без посторонней помощи.","Врач сам помогал ему подниматься по лестнице, потому что нога у него давно зажила.","Врач запретил ему подниматься по лестнице даже после того, как заживёт нога.","Пока нога не заживёт, ему нельзя подниматься по ступенькам самостоятельно, так велел врач."],"answer":5,"note":"запрет на самостоятельный подъём до выздоровления"},{"id":"2-056","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Начальник намекнул, что в следующем квартале сократят часть отдела, но имён не назвал»?","options":["Начальник пообещал, что сокращений не будет, но не уточнил, до какого времени.","Начальник отрицал, что в следующем квартале планируются какие-либо сокращения в отделе.","Начальник прямо объявил список тех, кого уволят в следующем квартале, и назвал все имена.","Сотрудники намекнули начальнику, что сокращать нужно именно тех, кого он не назвал.","Руководитель дал понять, что скоро часть сотрудников потеряет работу, однако никого конкретно не упомянул.","Отдел сократили ещё в прошлом квартале, а имён уволенных начальник так и не назвал."],"answer":4,"note":"намёк на сокращения без имён"},{"id":"2-057","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Нас заранее предупредили, что рейс могут задержать из-за тумана, поэтому мы приехали в аэропорт пораньше»?","options":["О задержке рейса из-за тумана нам сказали уже в аэропорту, когда мы приехали вовремя.","Нам сообщили заранее о возможной задержке самолёта из-за непогоды, и мы приехали в аэропорт с запасом времени.","Мы предупредили диспетчеров, что приедем в аэропорт пораньше из-за возможного тумана.","Нас предупредили, что туман рассеется к вечеру, и мы решили ехать в аэропорт позже.","Рейс задержали из-за тумана, о чём нас не предупредили, и мы приехали в аэропорт слишком рано.","Мы приехали в аэропорт пораньше, потому что рейс уже отменили из-за тумана."],"answer":1,"note":"заранее предупредили → приехали заранее"},{"id":"2-058","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Ему никак не удавалось сформулировать свою мысль так, чтобы собеседник понял её без дополнительных объяснений»?","options":["Собеседник легко понял его мысль с первого раза и ничего не просил объяснять.","Ему не удалось понять мысль собеседника, пока тот не дал дополнительных объяснений.","Он не мог выразить идею достаточно ясно, поэтому собеседнику требовались пояснения.","Собеседник долго формулировал свою мысль, а он помогал ему дополнительными объяснениями.","Он без труда объяснил свою мысль, и поэтому собеседнику пояснения были не нужны.","Он выразил мысль очень чётко, но собеседник отказался слушать любые объяснения."],"answer":2,"note":"не мог ясно выразить мысль"},{"id":"2-059","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Никто не посмел возразить директору, хотя его решение было явно ошибочным»?","options":["Сотрудники возразили директору только тогда, когда его решение уже было исполнено.","Все согласились с директором, потому что считали его решение абсолютно верным.","Директор принял решение, которое никто не посмел ему подсказать, но оно оказалось верным.","Решение директора было неверным, но спорить с ним никто не решился.","Директор не смог возразить сотрудникам, хотя его решение было совершенно ошибочным.","Все дружно возразили директору, потому что его решение показалось им ошибочным."],"answer":3,"note":"никто не посмел спорить"},{"id":"2-060","type":"wrong","stem":"Найдите предложение, в котором глагол употреблён неправильно.","options":["Я хочу поздравить тебя на день рождения.","Мы поблагодарили хозяев за тёплый приём.","Он пригрозил нам судом, если мы не вернём деньги.","Коллеги поздравили её с повышением по службе.","Она солгала мужу о том, где провела вечер.","Учитель повторил объяснение ещё раз для тех, кто не понял."],"answer":0,"note":"поздравить с чем-то"},{"id":"2-061","type":"wrong","stem":"Найдите предложение, в котором глагол употреблён неправильно.","options":["Врач попросил пациента показать, где болит.","Мы навестили к другу в больнице и принесли ему фрукты.","Директор запретил сотрудникам пользоваться личными телефонами на рабочем месте.","Он обещал позвонить, как только доберётся до места.","Каждое воскресенье она навещает бабушку в деревне.","Туристы посетили все главные музеи города за два дня."],"answer":1,"note":"навестить кого-то (без «к»)"},{"id":"2-062","type":"prefix","stem":"Стороны решили ___ договор сроком на пять лет с возможностью продления.","options":["отключить","сломать","исключить","включить","заключить","выключить"],"answer":4,"note":"заключить договор"},{"id":"2-063","type":"prefix","stem":"Благодаря упорству и терпению она ___ того, о чём многие только мечтали.","options":["добилась","сбила","убила","разбила","избила","забила"],"answer":0,"note":"добиться + род. п."},{"id":"2-064","type":"prefix","stem":"Накануне он так сильно волновался, что на следующий день ___ экзамен по математике.","options":["повалил","свалил","провалил","убил","отвалил","разбил"],"answer":2,"note":"провалить экзамен"},{"id":"2-065","type":"prefix","stem":"Никакие средства не помогли ___ с кафеля жирные пятна, которые уже въелись в швы.","options":["очистить","распилить","постирать","отмыть","помыть","домыть"],"answer":3,"note":"отмыть пятно"},{"id":"2-066","type":"prefix","stem":"Адвокату не удалось ___ присяжных в невиновности подзащитного.","options":["побороться","уничтожить","спасти","защитить","победить","убедить"],"answer":5,"note":"убедить кого в чём"},{"id":"2-067","type":"prefix","stem":"Он прицелился, но так и не решился ___ в человека.","options":["пристрелить","подстрелить","застрелить","ранить","убить","выстрелить"],"answer":5,"note":"выстрелить в + вин. п."},{"id":"2-068","type":"prefix","stem":"После долгих сомнений она решила ___ с ним раз и навсегда.","options":["сбросить","вырвать","порвать","взорвать","разбить","сломать"],"answer":2,"note":"порвать с кем-то"},{"id":"2-069","type":"prefix","stem":"Увидев драку, прохожий не выдержал и ___ в чужой конфликт.","options":["спас","вмешался","сломал","помешал","защитил","бросил"],"answer":1,"note":"вмешаться в"},{"id":"2-070","type":"prefix","stem":"Журналист не имел права ___ закон о защите свидетелей, публикуя их имена.","options":["нарушить","сломать","уничтожить","разрушить","испортить","взломать"],"answer":0,"note":"нарушить закон"},{"id":"2-071","type":"aspect","stem":"Рыбак забросил удочку и всего за минуту ___ огромного карася.","options":["хоронил","жалил","похоронил","ужалил","поймал","ловил"],"answer":4,"note":"за минуту → совершенный вид"},{"id":"2-072","type":"aspect","stem":"Адвокату удалось в последнюю минуту ___ подзащитного от несправедливого обвинения.","options":["жалить","защищать","душить","защитить","ужалить","задушить"],"answer":3,"note":"удалось + совершенный вид"},{"id":"2-073","type":"aspect","stem":"Достаточно один раз ___ на эту кнопку, и лифт сразу поедет.","options":["толкать","потянуть","тянуть","нажать","нажимать","толкнуть"],"answer":3,"note":"один раз → совершенный вид"},{"id":"2-074","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Полиция арестовала подозреваемого прямо в аэропорту, когда он собирался улететь за границу»?","options":["Полиция арестовала подозреваемого дома, когда он готовился к поездке за границу.","Подозреваемый сам пришёл в полицию, а потом уже собирался улететь за границу.","Подозреваемого задержали в аэропорту в тот момент, когда он готовился покинуть страну.","Подозреваемый улетел за границу раньше, чем полиция успела приехать в аэропорт.","Полиция отпустила подозреваемого в аэропорту, потому что он собирался улететь за границу.","Подозреваемый прилетел в аэропорт из-за границы, где его уже ждала полиция."],"answer":2,"note":"задержание в аэропорту перед вылетом"},{"id":"2-075","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Заложников освободили на рассвете, а преступников задержали несколькими часами позже»?","options":["Преступников освободили на рассвете, а заложников нашли только через несколько часов.","На рассвете преступники сами отпустили заложников, и больше никого задерживать не пришлось.","Преступников схватили на рассвете, а заложников удалось вывести из здания лишь через несколько часов.","Заложников держали ещё несколько часов после того, как на рассвете задержали преступников.","Заложников освободили вместе с преступниками, которых задержали несколькими часами позже.","Рано утром людей, которых удерживали силой, вызволили, и лишь позднее схватили виновных."],"answer":5,"note":"сначала освободили заложников, потом задержали преступников"},{"id":"2-076","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Один неудачный комментарий испортил всё впечатление от выступления, которое до этого было безупречным»?","options":["Выступление было безупречным до тех пор, пока одно неудачное замечание не разрушило хорошее впечатление.","После безупречного выступления слушатели сделали несколько неудачных замечаний, хотя впечатление не изменилось.","Комментарий был безупречным, но выступление после него потеряло всё своё хорошее впечатление.","Один неудачный комментарий усилил хорошее впечатление от выступления, которое и так было безупречным.","Неудачное выступление исправил один удачный комментарий, после которого впечатление стало хорошим.","Выступление с самого начала не понравилось слушателям, и комментарий лишь подтвердил это впечатление."],"answer":0,"note":"хорошее впечатление разрушено одним замечанием"},{"id":"2-077","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Когда речь коснулась денег, спокойный разговор сразу перерос в громкий спор»?","options":["Громкий спор начался после того, как собеседники перестали упоминать о деньгах.","Деньги появились в разговоре только тогда, когда спор давно закончился и все успокоились.","Собеседники вообще не говорили о деньгах, поэтому беседа оставалась спокойной до самого конца.","Разговор о деньгах начался с громкого спора, но быстро перешёл в спокойную беседу.","Как только собеседники заговорили о деньгах, мирная беседа тут же превратилась в шумную ссору.","Спор о деньгах закончился, и собеседники сразу заговорили о другом, но уже спокойно."],"answer":4,"note":"деньги → спор"},{"id":"2-078","type":"meaning","stem":"Какое предложение ближе всего по смыслу к предложению: «Банк ограбили средь бела дня, но грабителей так и не нашли, потому что никто не запомнил их лиц»?","options":["Банк ограбили ночью, и грабителей нашли быстро, потому что все запомнили их лица.","Налёт на банк произошёл днём, а преступников не обнаружили, поскольку свидетели не запомнили, как они выглядят.","Банк обокрали днём, но грабителей задержали, потому что кто-то запомнил их лица.","Грабители запомнили лица свидетелей, поэтому банк ограбили ночью, когда там никого не было.","Никто не запомнил лиц грабителей, поэтому банк решили не открывать до конца недели.","Грабителей нашли средь бела дня, хотя банк так и не был ограблен."],"answer":1,"note":"днём; не нашли из-за отсутствия описания"},{"id":"2-079","type":"wrong","stem":"Найдите предложение, в котором глагол употреблён неправильно.","options":["Ученики боролись над сложной задачей весь урок.","Лиса подкралась и поймала зайца у самой норы.","Народ боролся за свободу много лет.","Отряд боролся против врага до последнего патрона.","Он боролся с искушением и в итоге устоял.","Врачи борются за жизнь пациента уже вторые сутки."],"answer":0,"note":"над задачей работают/бьются; бороться над — ошибка"},{"id":"2-080","type":"wrong","stem":"Найдите предложение, в котором глагол употреблён неправильно.","options":["Он тянул верёвку на себя, пока та не порвалась.","Она нажала на тормоз, но машина не остановилась.","Хулиган толкнул у меня плечом и пошёл дальше.","Кто-то толкнул меня в толпе, и я уронил сумку.","Мальчик толкнул дверь рукой и вошёл в комнату.","Он ловко поймал мяч одной рукой."],"answer":2,"note":"толкнуть кого-то плечом"}]};
